{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("case missing threshold or calls")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    accepted = []
    diagnostics = []
    for idx, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError("each call must be a dict")
        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for key in required:
            if key not in call:
                raise ValueError(f"call missing {key}")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)):
            raise ValueError("loss_without_call must be numeric")
        if not isinstance(loss_with, (int, float)):
            raise ValueError("loss_with_call must be numeric")
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError("prediction_tokens must be positive int")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be bool")
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        stronger = max(loss_without, loss_with)
        normalized_gain_rounded = round(normalized_gain, 8)
        stronger_rounded = round(stronger, 8)
        diag = {
            'call_id': call_id,
            'normalized_gain': normalized_gain_rounded,
            'stronger_counterfactual': stronger_rounded
        }
        diagnostics.append(diag)
        if parseable and normalized_gain >= threshold:
            accepted.append(call_id)
    return {
        'accepted_call_ids': accepted,
        'diagnostics': diagnostics
    }"}
